import { isNil, startCase } from 'lodash-es';
import React from 'react';
import type { CellProps, ColumnInstance } from 'react-table';

import {
  FieldType,
  FieldTypeType,
  GeoPoint,
  RangedFieldTypes,
  ResultRecord,
  ResultRecordValue,
  Timeframe,
} from '@dynatrace-sdk/client-query';
import { format } from '@dynatrace-sdk/units';

import { cellRenderer } from './CellRenderers.js';
import { getTypesForRecordIndex } from './getFieldsArrayForRecordIndex.js';
import { formatDqlNumber } from './unit-utils.js';
import { _formatDate } from '../core/utils/create-datetime-default-formatter.js';
import { DataTable } from '../tables/DataTable/DataTable.js';
import { UseColumnTypesColumnOptions } from '../tables/plugins/use-column-types/useColumnTypes.js';
import {
  TableColumnAccessor,
  TableColumn,
  TableCellRenderer,
  SingleColumn,
  ColumnType,
  ColumnOptions,
} from '../tables/types/shared-table-types.js';

export function defaultSubColumnId(columnName: string, id: string) {
  return `${columnName}.${id}`;
}

type QueryFieldValue = ResultRecordValue | undefined;
type QueryRecord = ResultRecord;

type ColumnTypes = Map<string, Set<FieldTypeType>>;

/** Type for normalizing the cell value. Holds the cells value, the type and whether its a sub column */
type NormalizedQueryCellValue = {
  cellValue: QueryFieldValue;
  type: FieldType | undefined;
};

/** Type for the sub column accessor props. Holds the key for the sub column and its type */
type SubColumnAccessProps = { key: string; type: FieldTypeType };

type QueryCellValue =
  | {
      type: FieldTypeType | undefined;
      cellValue: undefined;
    }
  | {
      type: undefined;
      cellValue: ResultRecordValue | undefined;
    }
  | {
      type: FieldTypeType.Undefined;
      cellValue: null | undefined;
    }
  | {
      type: FieldTypeType.Boolean;
      cellValue: boolean;
    }
  | {
      type: FieldTypeType.Double | FieldTypeType.Long | FieldTypeType.Duration;
      cellValue: number;
    }
  | {
      type:
        | FieldTypeType.String
        | FieldTypeType.IpAddress
        | FieldTypeType.Timestamp;
      cellValue: string;
    }
  | {
      type: FieldTypeType.Timeframe;
      cellValue: Timeframe;
    }
  | {
      type: FieldTypeType.Record;
      cellValue: ResultRecord;
    }
  | {
      type: FieldTypeType.Array;
      cellValue: ResultRecordValue[];
    };

type DqlCellProps = Exclude<
  CellProps<QueryRecord, NormalizedQueryCellValue>,
  'column'
> & {
  column: ColumnInstance<QueryRecord> & QueryColumn;
};

export type QueryColumnCommon = SingleColumn & {
  types: FieldTypeType[];
  path: string[];
  queryColumnId: string;
  queryColumnName: string;
  columns?: QueryColumn[];
};

export type QueryColumn =
  | (QueryColumnCommon & {
      queryColumnType?: never;
      queryColumnRangedFieldTypes: RangedFieldTypes[];
    })
  | (QueryColumnCommon & {
      queryColumnType?: FieldType;
      queryColumnRangedFieldTypes?: never;
    });

/**
 * Creates a value accessor function for a given column.
 * Fallback value is an empty string
 */
function getValueAccessor(
  columnKey: string,
  rangedFieldTypes: RangedFieldTypes[],
  subColumn?: SubColumnAccessProps,
): TableColumnAccessor<QueryRecord> {
  return (originalRow: QueryRecord, index): string => {
    // If there is a sub column provided return a value access to the sub column field and define the type for the renderer
    if (subColumn?.key) {
      const subColumns = originalRow[columnKey];
      const subColumnKey = subColumn.key as keyof typeof subColumns;
      const cellValue =
        subColumns instanceof Object ? subColumns[subColumnKey] : subColumn;
      return convertQueryCellValue({
        cellValue,
        type: subColumn.type,
      } as QueryCellValue);
    }

    const cellValue = originalRow[columnKey];
    const typeEntry = getTypesForRecordIndex(rangedFieldTypes, index)?.mappings[
      columnKey
    ];

    return convertQueryCellValue({
      cellValue,
      type: typeEntry?.type,
    } as QueryCellValue);
  };
}

function convertQueryCellValue(value: QueryCellValue): string {
  const { cellValue, type } = value;

  if (cellValue === undefined || type === undefined) {
    return cellValue?.toString?.() ?? '';
  }

  // render `null` or `undefined` to the cell
  if (isNil(cellValue) || type === FieldTypeType.Undefined) {
    return '';
  }

  switch (type) {
    case FieldTypeType.Double:
    case FieldTypeType.Long: {
      return formatDqlNumber(cellValue, type);
    }
    case FieldTypeType.Duration: {
      return cellValue?.toString();
    }
    case FieldTypeType.Timestamp: {
      const dateValue = new Date(cellValue);
      return !isNaN(dateValue.getTime()) ? _formatDate(dateValue) : '';
    }
    case FieldTypeType.Timeframe: {
      const { start, end } = cellValue;
      return `[${start}, ${end}]`;
    }
    case FieldTypeType.Array:
    case FieldTypeType.Record: {
      return cellValue?.toString(); // only relevant for backward compatibility for DQLTableV2 (otherwise could return empty string)
    }
    case FieldTypeType.Boolean:
    case FieldTypeType.String:
    default: {
      return cellValue?.toString();
    }
  }
}

/** Returns a function to format the value for a given field type. */
function getCellRenderer(props: DqlCellProps) {
  const { row, column } = props;
  const {
    queryColumnType: type,
    queryColumnRangedFieldTypes: rangedFieldTypes,
    path,
    id: columnId,
  } = column;

  let typeEntry: FieldType | undefined;
  if (rangedFieldTypes) {
    typeEntry = getTypesForRecordIndex(rangedFieldTypes, row.index)?.mappings[
      columnId
    ];
  } else {
    typeEntry = type;
  }

  let cellValue: ResultRecordValue | undefined = undefined;
  for (const property of path as (keyof (
    | ResultRecord
    | Timeframe
    | GeoPoint
    | ResultRecordValue[]
  ))[]) {
    cellValue = (cellValue ?? row.original)[property];
    if (isNil(cellValue) || typeof cellValue !== 'object') {
      break;
    }
  }

  return <DataTable.Cell>{cellRenderer(cellValue, typeEntry)}</DataTable.Cell>;
}

/** Array of queryFieldTypes that should be split up into sub columns */
const SUB_COLUMN_TYPES: FieldTypeType[] = [
  FieldTypeType.Timeframe,
  FieldTypeType.GeoPoint,
];

/** Generates an array of sub columns based on the query field type. */
function generateSubColumns(
  type: FieldTypeType,
  columnName: string,
  rangedFieldTypes: RangedFieldTypes[],
): QueryColumn[] {
  const subColumns: QueryColumn[] = [];

  const subColumnAccessProps: SubColumnAccessProps[] = [];
  switch (type) {
    case 'timeframe':
      subColumnAccessProps.push(
        { key: 'start', type: FieldTypeType.Timestamp },
        { key: 'end', type: FieldTypeType.Timestamp },
      );
      break;
    case 'geo_point':
      subColumnAccessProps.push(
        { key: 'latitude', type: FieldTypeType.Double },
        { key: 'longitude', type: FieldTypeType.Double },
      );
      break;
  }

  subColumns.push(
    ...subColumnAccessProps.map((props) => {
      const columnType = getColumnType(props.type);
      return {
        header: props.key,
        accessor: getValueAccessor(columnName, rangedFieldTypes, props),
        cell: getCellRenderer,
        id: defaultSubColumnId(columnName, props.key),
        types: [props.type],
        path: [columnName, props.key],
        queryColumnId: props.key,
        queryColumnName: props.key,
        columnType,
        queryColumnType: { type: props.type },
        alignment: getAlignmentBasedOnType(columnType),
      };
    }),
  );
  return subColumns;
}

/** Generates column definitions for the data table including sub columns. */
function generateColumns(
  columnTypes: ColumnTypes,
  rangedFieldTypes: RangedFieldTypes[],
  columnOptionsFn?: (column: TableColumn) => Partial<ColumnOptions>,
): QueryColumn[] {
  return [...columnTypes.keys()].map((columnKey) => {
    const types = columnTypes.get(columnKey) ?? new Set();

    const typesArray = [...types.values()];
    const columnHasOnlyOneType = typesArray.length === 1;
    const shouldSplitIntoSubColumns =
      columnHasOnlyOneType && SUB_COLUMN_TYPES.includes(typesArray[0]);
    // const queryColumnType = { type: typesArray[0], types: rangedFieldTypes };
    const queryColumnRangedFieldTypes = rangedFieldTypes;

    let result: QueryColumn | null = null;
    if (shouldSplitIntoSubColumns) {
      result = {
        header: columnKey,
        id: columnKey,
        columns: generateSubColumns(typesArray[0], columnKey, rangedFieldTypes),
        types: typesArray,
        path: [columnKey],
        queryColumnId: columnKey,
        queryColumnName: columnKey,
        queryColumnRangedFieldTypes,
      };
    } else {
      let columnType: UseColumnTypesColumnOptions['columnType'] | undefined;

      if (columnHasOnlyOneType) {
        columnType = getColumnType(typesArray[0]);
      }

      result = {
        header: columnKey,
        id: columnKey,
        accessor: getValueAccessor(columnKey, rangedFieldTypes),
        cell: getCellRenderer,
        types: typesArray,
        path: [columnKey],
        queryColumnId: columnKey,
        queryColumnName: columnKey,
        queryColumnRangedFieldTypes,
        columnType,
        alignment: getAlignmentBasedOnType(columnType),
      };
    }
    const columnOptions = columnOptionsFn ? columnOptionsFn(result) : {};
    return { ...result, ...columnOptions };
  });
}

/** Extracts the column types from query records. */
function extractColumnTypes(rangedFieldTypes: RangedFieldTypes[]): ColumnTypes {
  const columnTypes = new Map<string, Set<FieldTypeType>>();

  rangedFieldTypes.forEach(({ mappings }) => {
    Object.keys(mappings).forEach((key) => {
      const type = mappings[key]?.type ?? FieldTypeType.String;
      if (columnTypes.has(key)) {
        columnTypes.get(key)?.add(type);
      } else {
        columnTypes.set(key, new Set([type]));
      }
    });
  });

  return columnTypes;
}

/**
 * Converts well-formed array data into table columns.
 * Well-formed means that every object within that array has the same keys.
 * @param data - well-formed json (array of objects with identical keys)
 * @returns columns with 'id', 'header', 'accessor' and 'cell'  set.
 */
export function convertToColumnsFromWellFormedArray(
  data: Record<string, unknown>[],
): TableColumn[] {
  const firstRow = data[0]; // just take the first one, assuming all have identical keys
  return Object.keys(firstRow).map<TableColumn>((key: string): TableColumn => {
    const header = startCase(key);

    // Note: Dots in accessor strings have a special meaning
    // for accessing sub columns, so to avoid the table
    // wrongly looking for a sub column when the original
    // accessor name has dots in it, we provide an
    // accessor function instead of using the key string directly.
    const accessorFunc = (row: Record<string, unknown>) => {
      return row[key];
    };

    const cellRenderer = getBasicCellRenderer(accessorFunc, firstRow);

    return {
      id: key,
      header: header,
      accessor: accessorFunc,
      cell: cellRenderer,
    } as TableColumn;
  });
}

type BasicCellRenderer = TableCellRenderer<
  CellProps<Record<string, unknown>, Record<string, unknown>>
>;

/**
 * Intended for usage with the well-formed array data conversion.
 * @param accessorFunc - function used to access the data
 * @param row - sample row of data e.g. the first row.
 * @returns a cellRenderer appropriate for the type of data in a column.
 */
function getBasicCellRenderer(
  accessorFunc: (row: Record<string, unknown>) => unknown,
  row: Record<string, unknown>,
): BasicCellRenderer {
  // Note: more cellRenderers for different 'types' like dates in strings can be added here in future.
  let cellRenderer: BasicCellRenderer = (props: {
    value: number | string;
  }): string => {
    return props.value as string;
  };
  if (typeof accessorFunc(row) === 'number') {
    cellRenderer = (props: { value: number | string }): string => {
      return format(props.value as number, {
        abbreviate: true,
        maximumFractionDigits: 3,
      });
    };
  }
  return cellRenderer;
}

/** Mapping queryfieldtypes to table column types */
function getColumnType(
  columnType: FieldTypeType,
): UseColumnTypesColumnOptions['columnType'] {
  switch (columnType) {
    case FieldTypeType.Timestamp:
      return 'date';
    case FieldTypeType.Long:
    case FieldTypeType.Double:
    case FieldTypeType.Duration:
      return 'number';
  }
  return 'text';
}

/**
 * Converts given query field types to table columns.
 * @param rangedFieldTypes - Field types
 * @param columnOptionsFn - function providing options to be applied to columns e.g. `return {ratioWidth: 1}`
 */
export function convertToColumns(
  rangedFieldTypes: RangedFieldTypes[],
  columnOptionsFn?: (column: TableColumn) => Partial<ColumnOptions>,
): QueryColumn[] {
  const types = extractColumnTypes(rangedFieldTypes);
  return generateColumns(types, rangedFieldTypes, columnOptionsFn);
}

function getAlignmentBasedOnType(
  columnType: ColumnType | undefined,
): 'left' | 'right' {
  switch (columnType) {
    case 'number':
    case 'bit':
    case 'date':
      return 'right';
    default:
      return 'left';
  }
}
